      "codeSnippet": "// middleware/cache.js\nimport { redis } from \"../config/redis.js\";\n\nexport const cache = (durationInSeconds = 300) => async (req, res, next) => {\n  if (req.method !== \"GET\") return next();\n\n  const key = `cache:${req.originalUrl}`;\n  try {\n    const cachedData = await redis.get(key);\n    if (cachedData) {\n      return res.status(200).json(JSON.parse(cachedData));\n    }\n\n    // Intercept res.json to capture response before sending\n    const originalJson = res.json.bind(res);\n    res.json = (body) => {\n      // Store in Redis with TTL\n      redis.set(key, JSON.stringify(body), \"EX\", durationInSeconds);\n      return originalJson(body);\n    };\n\n    next();\n  } catch (err) {\n    next(); // On cache failure, gracefully proceed to database\n  }\n};"
